mapper.select:
SELECT source_data.ORDER_NO, source_data.SCHEDULE_DATE, source_data.SIDEWALL_CODE AS PADDING_CODE, source_data.NIGHT_FINISH_QTY, source_data.DAY_FINISH_QTY, source_data.MID_FINISH_QTY, source_data.FACTORY_CODE FROM MES_NC_CLASS_FINISH_QTY source_data INNER JOIN ( SELECT SCHEDULE_DATE, SIDEWALL_CODE, ORDER_NO, MAX(DATA_VERSION) AS MAX_VERSION FROM MES_NC_CLASS_FINISH_QTY WHERE CONVERT(DATE, SCHEDULE_DATE) = CONVERT(DATE, GETDATE())
AND FACTORY_CODE = #{factoryCode}
AND COMPANY_CODE = #{companyCode}
AND DATA_VERSION = #{dataVersion}
GROUP BY SCHEDULE_DATE, SIDEWALL_CODE, ORDER_NO, FACTORY_CODE, COMPANY_CODE ) latest ON source_data.SCHEDULE_DATE = latest.SCHEDULE_DATE AND source_data.SIDEWALL_CODE = latest.SIDEWALL_CODE AND source_data.ORDER_NO = latest.ORDER_NO AND source_data.FACTORY_CODE = latest.FACTORY_CODE AND source_data.COMPANY_CODE = latest.COMPANY_CODE AND source_data.DATA_VERSION = latest.MAX_VERSION WHERE CONVERT(DATE, source_data.SCHEDULE_DATE) = CONVERT(DATE, GETDATE())
AND source_data.FACTORY_CODE = #{factoryCode}
AND source_data.COMPANY_CODE = #{companyCode}
AND source_data.DATA_VERSION = #{dataVersion}

SELECT source_data.SCHEDULE_DATE, source_data.SIDEWALL_CODE AS LINING_CODE, source_data.FINISH_QTY AS DAY_FINISH_QTY, CAST(0 AS DECIMAL(18, 6)) AS NIGHT_FINISH_QTY, CAST(0 AS DECIMAL(18, 6)) AS MID_FINISH_QTY, '' AS ORDER_NO, source_data.FACTORY_CODE FROM MES_NC_DAY_FINISH_TOTL source_data INNER JOIN ( SELECT SCHEDULE_DATE, SIDEWALL_CODE, FACTORY_CODE, COMPANY_CODE, MAX(DATA_VERSION) AS MAX_VERSION FROM MES_NC_DAY_FINISH_TOTL WHERE 1 = 1
AND FACTORY_CODE = #{factoryCode}
AND COMPANY_CODE = #{companyCode}
AND DATA_VERSION = #{dataVersion}
AND CONVERT(DATE, SCHEDULE_DATE) = CONVERT(DATE, #{queryParams.scheduleDate})
GROUP BY SCHEDULE_DATE, SIDEWALL_CODE, FACTORY_CODE, COMPANY_CODE ) latest ON source_data.SCHEDULE_DATE = latest.SCHEDULE_DATE AND source_data.SIDEWALL_CODE = latest.SIDEWALL_CODE AND source_data.FACTORY_CODE = latest.FACTORY_CODE AND source_data.COMPANY_CODE = latest.COMPANY_CODE AND source_data.DATA_VERSION = latest.MAX_VERSION WHERE 1 = 1
AND source_data.FACTORY_CODE = #{factoryCode}
AND source_data.COMPANY_CODE = #{companyCode}
AND source_data.DATA_VERSION = #{dataVersion}
AND CONVERT(DATE, source_data.SCHEDULE_DATE) = CONVERT(DATE, #{queryParams.scheduleDate})
